/**
 * Returns true when the stored ad image URL is a real, displayable URL.
 * Filters out broken values such as PHP temp upload paths ("/tmp/phpXXXX")
 * that were saved when a File was sent under `image_url`.
 */
export function isValidStoredAdImageUrl(url: unknown): url is string {
  if (typeof url !== "string") return false;
  const clean = url.trim();
  if (!clean || clean === "null" || clean === "undefined") return false;
  if (/^\/?tmp\//i.test(clean) || /[\\/]php[A-Za-z0-9]+$/.test(clean)) return false;
  if (clean.startsWith("data:") || clean.startsWith("blob:")) return false;
  return true;
}

/**
 * Appends the ad image fields to an update FormData.
 * - New file selected  -> send the file under `image_url` (same field as create;
 *   the backend update must store it via `$request->file('image_url')->store(...)`).
 * - Image removed      -> send empty `image_url` to clear it.
 * - Unchanged          -> re-send the existing `image_url` string so the backend
 *   does not overwrite it with null.
 */
export function appendAdImageToFormData(
  formData: FormData,
  newImage: File | null,
  preview: string,
  existingImageUrl: unknown,
) {
  if (newImage) {
    formData.append("image_url", newImage);
    return;
  }

  if (!preview) {
    formData.append("image_url", "");
    return;
  }

  if (isValidStoredAdImageUrl(existingImageUrl)) {
    formData.append("image_url", existingImageUrl.trim());
  }
}
